syntax:
for (type variable = initial_value; termination_condition; increment_expression) {
    // loop body
}

// where 'termination_condition' may involve volatile variables or complex expressions to handle external or asynchronous events

code_example:
volatile size_t ix = 0;
for (; ix != 10; ++ix) {
    // Loop body that depends on external hardware or asynchronous signals
    // For example, waiting for a hardware flag to change
}
